<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Salary Paid Slip</h1><p>Select and print a persisted salary payment.</p></div></header><?php if(!$slip):?><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>Employee</th><th>Month</th><th>Paid</th><th>Date</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach($payments as$p):?><tr><td><?= e($p['employee_no'].' — '.$p['name']) ?></td><td><?= e($p['salary_month']) ?></td><td><?= number_format((float)$p['paid_amount'],2) ?></td><td><?= e($p['payment_date']) ?></td><td><a class="btn btn--secondary" href="<?= url('/admin/salary/receipt/'.$p['id']) ?>">Open Slip</a></td></tr><?php endforeach ?></tbody></table></div></section><?php else:?><section class="module-card"><header class="module-card__header"><div><h2><?= e($slip['institute_name']) ?></h2><p>Salary payment receipt</p></div><button class="btn btn--primary" onclick="window.print()">Print</button></header><div class="module-card__body"><table class="data-table"><tbody><tr><th>Employee</th><td><?= e($slip['employee_no'].' — '.$slip['name']) ?></td></tr><tr><th>Designation</th><td><?= e($slip['role']) ?></td></tr><tr><th>Salary Month</th><td><?= e($slip['salary_month']) ?></td></tr><tr><th>Base Salary</th><td><?= number_format((float)$slip['base_salary'],2) ?></td></tr><tr><th>Adjustment (net)</th><td><?= number_format((float)$slip['adjustment_amount'],2) ?></td></tr><?php if((float)($slip['deduction_amount']??0)>0):?><tr><th>Deduction</th><td>-<?= number_format((float)$slip['deduction_amount'],2) ?></td></tr><?php endif ?><?php if((float)($slip['advance_recovered']??0)>0):?><tr><th>Advance Recovered</th><td>-<?= number_format((float)$slip['advance_recovered'],2) ?></td></tr><?php endif ?><tr><th>Paid Amount</th><td><?= number_format((float)$slip['paid_amount'],2) ?></td></tr><tr><th>Payment Date</th><td><?= e($slip['payment_date']) ?></td></tr><tr><th>Reference</th><td><?= e($slip['reference']?:'—') ?></td></tr><tr><th>Remarks</th><td><?= e($slip['remarks']?:'—') ?></td></tr></tbody></table></div></section><?php endif ?></div></div></main>
